from hypothesis import given, strategies as st

@given(st.lists(st.floats()))
def test_roundtrip(xs):                    # property 1 — serializer is bug-free
    assert decode(encode(xs)) == xs

@given(st.integers(0, 10**6))
def test_enrich(cents):                    # property 2 — enrich() calls a sandbox API,
    assert enrich(cents).total >= cents    #   each call takes ~300 ms

@given(st.text())
def test_parse_never_raises(s):            # property 3 — parse() of a strict format
    parse(s)                               #   (it raises ParseError on bad input)

